// A typed client for the core API. The types come from api/openapi.yaml:
// src/schema.d.ts is generated by "mise run gen". Do not edit it by hand.
import createClient from "openapi-fetch";
import type { paths } from "./schema";

export type { components, paths } from "./schema";
export { ApiError, fieldErrors, problemKind, toProblem, unwrap } from "./problem";
export type { Problem, ProblemKind } from "./problem";
// The zod schemas of the contract, for forms (@mantine/form schemaResolver).
export * from "./gen/zod.gen";

export function createApiClient(baseUrl: string) {
  return createClient<paths>({ baseUrl });
}
